def add(id,group,q,sql,types,notes,cross=False,ordered=True,oracle_sql=None,oracle_rows=None):
 q=re.sub(r'(?<=[A-Za-z])(?=\d)|(?<=\d)(?=[A-Za-z])',' ',q);notes=re.sub(r'(?<=[A-Za-z])(?=\d)|(?<=\d)(?=[A-Za-z])',' ',notes)
 rows=oracle_rows if oracle_rows is not None else db.execute(oracle_sql or sql).fetchall();names=[d[0] for d in db.execute(oracle_sql or sql).description]
 typed=[]
 for r in rows:
  typed.append([None if v is None else bool(v) if t=='boolean' else format(Decimal(str(v)).quantize(Decimal(1).scaleb(-int(t.split(',')[1][:-1]))),'f') if t.startswith('decimal') else str(v) if t.startswith('int') else v for v,t in zip(r,types)])
 write('expected/'+id+'.json',{'outcome':'result','columns':[dict({'name':n,'type':t},**({'tolerance':{'absolute':1e-10,'relative':1e-12}} if t=='float64' and id in ['fanout.weighted_price','fanout.refund_fraction'] else {})) for n,t in zip(names,types)],'rows':typed})
 cases.append({'id':id,'primary_group':group,'tags':[group]+(['cross_source'] if cross else []),'question':q,'sql':sql,'expected':'expected/'+id+'.json','comparison':{'ordered':ordered,'assert_names':False,'assert_physical_types':id in ['projection.width','projection.float','calendar.fraction','calendar.autumn_instant','calendar.spring_wall']},'requirements':[notes],'oracle_reasoning':('Independent Python Decimal/reference arithmetic over canonical records. ' if oracle_rows is not None else 'Independent SQLite relational evaluation over canonical records; exact integer arithmetic for CHF cents. ')+notes,'distinguishing_rows':[notes]})
add('projection.vip','projection','List VIP customer IDs then names, ascending customer ID.','SELECT customer_id,name FROM customers WHERE vip = true ORDER BY customer_id',['int32','utf8'],'Customers 1 and 3 are VIP; customer 2 is not.')
add('projection.empty','projection','Which customers have an explicitly empty note? Return IDs ascending.','SELECT customer_id FROM customers WHERE note = \'\' ORDER BY customer_id',['int32'],'Customers 1 and 4 empty; 2 and 5 null.')
add('projection.null','projection','Which customers have unknown notes? Return IDs ascending.','SELECT customer_id FROM customers WHERE note IS NULL ORDER BY customer_id',['int32'],'Customers 2 and 5 null, distinct from empty.')
add('roles.billing','relationships','For completed orders, list order ID then billed buyer name; omit unmatched buyers and sort by order ID.','SELECT o.order_id,c.name FROM orders o JOIN customers c ON o.billing_customer_id=c.customer_id WHERE o.status=\'completed\' ORDER BY o.order_id',['int64','utf8'],'101 bills Ada but ships Béatrice; 109 has unmatched billing ID99.',True)
add('roles.shipping','relationships','List every order ID then recipient name, retaining unknown recipients, by order ID.','SELECT o.order_id,c.name FROM orders o LEFT JOIN customers c ON o.shipping_customer_id=c.customer_id ORDER BY o.order_id',['int64','utf8'],'101 ships Béatrice not Ada;105 unknown recipient;109 recipient Ada despite unmatched payer.',True)
add('metrics.gross','aggregations','What is gross completed sales in exact CHF cents?','SELECT SUM(total_minor) AS gross_minor FROM orders WHERE status=\'completed\'',['int64'],'101 2500,102 2000,104 3000,106 2000,107 1500,108 -100,109 500,110 500; sum11900.')
add('relationships.products','relationships','List order ID, line number, then product name for every line; keep unknown products and sort by order then line.','SELECT i.order_id,i.line_no,p.name FROM order_items i LEFT JOIN products p ON i.product_id=p.product_id ORDER BY i.order_id,i.line_no',['int64','int16','utf8'],'109 product999 unmatched;101 has two different product lines.',True)
add('absence.buyers','existence','Which customer IDs and names have no billed orders of any status? Sort by ID.','SELECT c.customer_id,c.name FROM customers c WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.billing_customer_id=c.customer_id) ORDER BY c.customer_id',['int32','utf8'],'Customer6 never ordered;2 only cancelled/pending but still has orders.',True)
add('fanout.net','multiple_facts','What are completed gross sales minus all refunds linked to completed orders, in CHF cents?','SELECT (SELECT SUM(total_minor) FROM orders WHERE status=\'completed\')-(SELECT SUM(r.refund_minor) FROM refunds r JOIN orders o ON r.order_id=o.order_id WHERE o.status=\'completed\') AS net_minor',['int64'],'Gross11900 minus1600 =10300;101 has two items and two refunds, so raw three-way joins multiply totals.')
add('history.boundary','historical','For Ada’s billed orders, list order ID then historical region at the order date; keep missing history and sort by order ID.','SELECT o.order_id,h.region FROM orders o LEFT JOIN customer_region_history h ON o.billing_customer_id=h.customer_id AND h.valid_from<=o.order_date AND (h.valid_to IS NULL OR o.order_date<h.valid_to) WHERE o.billing_customer_id=1 ORDER BY o.order_id',['int64','utf8'],'101 before Jan1 regionDE;102 exactly boundary regionCH;107 CH. Half-open history.')
