# Multiple fact correctness (10 total)
add('fanout.order_item','multiple_facts','For completed orders, return total order cents then total item cents using independent aggregation.',"SELECT (SELECT SUM(total_minor) FROM orders WHERE status='completed') AS orders_minor,(SELECT SUM(i.line_minor) FROM order_items i JOIN orders o ON i.order_id=o.order_id WHERE o.status='completed') AS items_minor",['int64','int64'],'Both11900; order101 must count once despite2lines.')
add('fanout.per_buyer_net','multiple_facts','Return each known billed buyer name then completed sales minus linked refunds in cents, by customer ID.',"WITH r AS (SELECT order_id,SUM(refund_minor) AS refunded FROM refunds GROUP BY order_id) SELECT c.name,SUM(o.total_minor-COALESCE(r.refunded,0)) AS net_minor FROM customers c JOIN orders o ON c.customer_id=o.billing_customer_id LEFT JOIN r ON o.order_id=r.order_id WHERE o.status='completed' GROUP BY c.customer_id,c.name ORDER BY c.customer_id",['utf8','int64'],'Ada5500,Chen2400,Dario2000,Éva-100; refund101 summed500 once.',True)
add('fanout.line_refunds','multiple_facts','For every line of order101 return line number, line cents, then total refund cents, using zero for lines without refunds; sort by line number.',"WITH r AS (SELECT order_id,line_no,SUM(refund_minor) AS cents FROM refunds GROUP BY order_id,line_no) SELECT i.line_no,i.line_minor,COALESCE(r.cents,0) AS refunded FROM order_items i LEFT JOIN r ON i.order_id=r.order_id AND i.line_no=r.line_no WHERE i.order_id=101 ORDER BY i.line_no",['int16','int64','int64'],'Line1 1000 refunded500;line2 1500 refunded0. Composite grouped join.')
add('fanout.orders_subscriptions','multiple_facts','For every customer return name, completed billed sales cents (zero if none), then active monthly cents on April1, by ID.',"WITH o AS (SELECT billing_customer_id,SUM(total_minor) AS cents FROM orders WHERE status='completed' GROUP BY billing_customer_id),s AS (SELECT customer_id,SUM(monthly_minor) AS cents FROM subscriptions WHERE status='active' AND start_date<='2024-04-01' AND (end_date IS NULL OR '2024-04-01'<end_date) GROUP BY customer_id) SELECT c.name,COALESCE(o.cents,0),COALESCE(s.cents,0) FROM customers c LEFT JOIN o ON c.customer_id=o.billing_customer_id LEFT JOIN s ON c.customer_id=s.customer_id ORDER BY c.customer_id",['utf8','int64','int64'],'Ada3orders and2subscriptions would multiply; active1 only atApr1.',True)
add('fanout.product_net','multiple_facts','For items with matching catalog product records, return product name then completed item sales minus line refunds in cents, by product ID.',"WITH r AS (SELECT order_id,line_no,SUM(refund_minor) AS cents FROM refunds GROUP BY order_id,line_no) SELECT p.name,SUM(i.line_minor-COALESCE(r.cents,0)) AS net_minor FROM products p JOIN order_items i ON p.product_id=i.product_id JOIN orders o ON i.order_id=o.order_id LEFT JOIN r ON i.order_id=r.order_id AND i.line_no=r.line_no WHERE o.status='completed' GROUP BY p.product_id,p.name ORDER BY p.product_id",['utf8','int64'],'Tea3400 minus600=2800;Mug6000 minus1000=5000;Book2000.',True)
add('fanout.weighted_price','multiple_facts','For items with matching catalog product records, return product name then weighted completed unit price in cents, using signed quantity and null when zero, rounded half away from zero to six decimals, by product ID.',"SELECT p.name,CAST(ROUND(CAST(SUM(i.line_minor) AS DECIMAL(18,6))/NULLIF(CAST(SUM(i.quantity) AS DECIMAL(18,6)),0),6) AS DECIMAL(18,6)) AS weighted_price FROM products p JOIN order_items i ON p.product_id=i.product_id JOIN orders o ON i.order_id=o.order_id WHERE o.status='completed' GROUP BY p.product_id,p.name ORDER BY p.product_id",['utf8','decimal128(18,6)'],'Tea3400/3 rounds1133.333333, not mean of line prices;Mug1500;Book2000.',True,oracle_rows=[(name,format((Decimal(sum(r[4] for r in tables['order_items'][2] if r[2]==pid and r[0] in {o[0] for o in tables['orders'][2] if o[3]=='completed'}))/Decimal(sum(r[3] for r in tables['order_items'][2] if r[2]==pid and r[0] in {o[0] for o in tables['orders'][2] if o[3]=='completed'}))).quantize(Decimal('0.000001'),rounding=ROUND_HALF_UP),'f')) for pid,name,*_ in tables['products'][2] if pid in (10,20,30)])
add('fanout.order_refund_count','multiple_facts','Return each known buyer name, completed order count, then linked refund event count, by buyer ID.',"WITH r AS (SELECT order_id,COUNT(*) AS events FROM refunds GROUP BY order_id) SELECT c.name,COUNT(o.order_id),SUM(COALESCE(r.events,0)) FROM customers c JOIN orders o ON c.customer_id=o.billing_customer_id LEFT JOIN r ON o.order_id=r.order_id WHERE o.status='completed' GROUP BY c.customer_id,c.name ORDER BY c.customer_id",['utf8','int64','int64'],'Ada3 orders2refund events;Chen2orders2events;Dario1/1zero event.',True)
add('fanout.refund_fraction','multiple_facts','Return billed buyer name then refunded cents divided by completed gross cents as float, by buyer ID.',"WITH r AS (SELECT order_id,SUM(refund_minor) AS cents FROM refunds GROUP BY order_id) SELECT c.name,SUM(COALESCE(r.cents,0))*1.0/NULLIF(SUM(o.total_minor),0) AS refund_fraction FROM customers c JOIN orders o ON c.customer_id=o.billing_customer_id LEFT JOIN r ON o.order_id=r.order_id WHERE o.status='completed' GROUP BY c.customer_id,c.name ORDER BY c.customer_id",['utf8','float64'],'Ratio of sums: Ada500/6000,Chen1100/3500,Dario0/2000,Éva0/-100.',True)
add('fanout.line_count','multiple_facts','Return completed order ID, item count, then refund event count with absent events zero, ordered by order ID.',"WITH i AS (SELECT order_id,COUNT(*) AS lines FROM order_items GROUP BY order_id),r AS (SELECT order_id,COUNT(*) AS events FROM refunds GROUP BY order_id) SELECT o.order_id,COALESCE(i.lines,0),COALESCE(r.events,0) FROM orders o LEFT JOIN i ON o.order_id=i.order_id LEFT JOIN r ON o.order_id=r.order_id WHERE o.status='completed' ORDER BY o.order_id",['int64','int64','int64'],'1012lines2events not4 each;1021line0events.')
# Temporal (10)
add('calendar.leap','temporal','List order ID then billed customer name for orders on leap day2024 with matching billed customer records, by ID.',"SELECT o.order_id,c.name FROM orders o JOIN customers c ON o.billing_customer_id=c.customer_id WHERE o.order_date=DATE '2024-02-29' ORDER BY o.order_id",['int64','utf8'],'104 Chen leap day only.',True,oracle_sql="SELECT o.order_id,c.name FROM orders o JOIN customers c ON o.billing_customer_id=c.customer_id WHERE o.order_date='2024-02-29' ORDER BY o.order_id")
add('calendar.previous_month','temporal','Using the fixed April1 2024 request clock, list completed March order IDs and payer names, excluding orders without a matching billed customer record, by ID.',"SELECT o.order_id,c.name FROM orders o JOIN customers c ON o.billing_customer_id=c.customer_id WHERE o.status='completed' AND o.order_date>=DATE '2024-03-01' AND o.order_date<DATE '2024-04-01' ORDER BY o.order_id",['int64','utf8'],'106,107 March;105 pending;108 Apr boundary.',True,oracle_sql="SELECT o.order_id,c.name FROM orders o JOIN customers c ON o.billing_customer_id=c.customer_id WHERE o.status='completed' AND o.order_date>='2024-03-01' AND o.order_date<'2024-04-01' ORDER BY o.order_id")
add('calendar.fiscal','temporal','Return fiscal year then completed gross sales cents using the calendar, ordered by fiscal year.',"SELECT c.fiscal_year,SUM(o.total_minor) FROM orders o JOIN business_calendar c ON o.order_date=c.calendar_date WHERE o.status='completed' GROUP BY c.fiscal_year ORDER BY c.fiscal_year",['int32','int64'],'FY2023 11000;FY2024 900.',True)
add('calendar.business_day','temporal','List completed order IDs that fall on authored business days, ascending.',"SELECT o.order_id FROM orders o JOIN business_calendar c ON o.order_date=c.calendar_date WHERE o.status='completed' AND c.business_day=true ORDER BY o.order_id",['int64'],'Leap104 andSunday106107 excluded by authored flag.',True)
add('calendar.monthly','temporal','Return calendar month key then completed sales cents for months with sales, sorted by month.',"SELECT c.month_key,SUM(o.total_minor) FROM orders o JOIN business_calendar c ON o.order_date=c.calendar_date WHERE o.status='completed' GROUP BY c.month_key ORDER BY c.month_key",['utf8','int64'],'December2500 January2000 February3000 March3500 April-100 October1000.',True)
add('calendar.missing_month','temporal','Return each distinct authored calendar month then completed sales cents, zero for no completed sales, by month.',"WITH m AS (SELECT DISTINCT month_key FROM business_calendar),o AS (SELECT c.month_key,SUM(o.total_minor) AS cents FROM orders o JOIN business_calendar c ON o.order_date=c.calendar_date WHERE o.status='completed' GROUP BY c.month_key) SELECT m.month_key,COALESCE(o.cents,0) FROM m LEFT JOIN o ON m.month_key=o.month_key ORDER BY m.month_key",['utf8','int64'],'Authored May has no sales and must appear zero; June-September unlisted months are not fabricated.',True)
add('calendar.spring_wall','temporal','Return order IDs and local timestamps for the Zurich DST jump orders106 and107, by ID.',"SELECT order_id,local_placed_at FROM orders WHERE order_id IN (106,107) ORDER BY order_id",['int64','timestamp(us)'],'Wall01:30 and03:30; UTC instants only1hour apart.')
add('calendar.autumn_instant','temporal','Return order ID then UTC placed instant for autumn repeated-wall-hour orders109 and110, by ID.',"SELECT order_id,placed_at FROM orders WHERE order_id IN (109,110) ORDER BY order_id",['int64','timestamp(us,UTC)'],'UTC00:30 and01:30 are distinct though both wall02:30.')
add('calendar.fraction','temporal','Return order date, local timestamp, then pickup time for order101.',"SELECT order_date,local_placed_at,pickup_time FROM orders WHERE order_id=101",['date32','timestamp(us)','time64(us)'],'Fraction123456 preserved; separate date,time,wall timestamp types.')
add('calendar.year_boundary','temporal','Return order ID then local order date for orders101 and102, by ID.',"SELECT order_id,order_date FROM orders WHERE order_id IN (101,102) ORDER BY order_id",['int64','date32'],'Both UTCDec31 but local dates Dec31/Jan1.')
# History (6 total)
hjoin=" FROM orders o LEFT JOIN customer_region_history h ON o.billing_customer_id=h.customer_id AND h.valid_from<=o.order_date AND (h.valid_to IS NULL OR o.order_date<h.valid_to) "
add('history.missing','historical','Return order ID then historical payer region for Chen’s orders, retaining unknown history, by order ID.',"SELECT o.order_id,h.region"+hjoin+"WHERE o.billing_customer_id=3 ORDER BY o.order_id",['int64','utf8'],'104 beforeMarch1 null,110 CH; never replace missing with currentCH.')
add('history.current_vs_then','historical','For orders101 and102 with matching current billed customer records, return ID, current payer region, then payer region at order date, retaining missing historical matches as null, by ID.',"SELECT o.order_id,c.region,h.region"+hjoin+"JOIN customers c ON o.billing_customer_id=c.customer_id WHERE o.order_id IN (101,102) ORDER BY o.order_id",['int64','utf8','utf8'],'101 currentCH historicalDE;102 bothCH.',True)
add('history.all','historical','List completed order ID, payer name, then historical region, retaining missing names and histories, by order ID.',"SELECT o.order_id,c.name,h.region"+hjoin+"LEFT JOIN customers c ON o.billing_customer_id=c.customer_id WHERE o.status='completed' ORDER BY o.order_id",['int64','utf8','utf8'],'104 historynull;109 nameregionnull;101 DE despite currentCH.',True)
add('history.region_sales','historical','Return historical payer region then completed sales cents, excluding missing history, ordered by region.',"SELECT h.region,SUM(o.total_minor) FROM orders o JOIN customer_region_history h ON o.billing_customer_id=h.customer_id AND h.valid_from<=o.order_date AND (h.valid_to IS NULL OR o.order_date<h.valid_to) WHERE o.status='completed' GROUP BY h.region ORDER BY h.region",['utf8','int64'],'AT-100 CH4000 DE4500;1043000 and109500 unmatched excluded.')
add('history.changed','historical','Return order IDs and buyer names where current payer region differs from known historical payer region, by ID.',"SELECT o.order_id,c.name"+hjoin+"JOIN customers c ON o.billing_customer_id=c.customer_id WHERE c.region<>h.region ORDER BY o.order_id",['int64','utf8'],'Only101 Ada;null history does not satisfy inequality.',True)
# Windows (8)
add('window.rank','windows','Return completed order ID, cents, then dense rank by descending cents, sorted by cents descending then ID.',"SELECT order_id,total_minor,DENSE_RANK() OVER (ORDER BY total_minor DESC) AS sales_rank FROM orders WHERE status='completed' ORDER BY total_minor DESC,order_id",['int64','int64','int64'],'102/106 tie rank3;109/110 tie rank5; next ranks no gaps.')
add('window.rank_gaps','windows','Return completed order ID then competition rank by descending cents, ordered by cents descending then ID.',"SELECT order_id,RANK() OVER (ORDER BY total_minor DESC) AS sales_rank FROM orders WHERE status='completed' ORDER BY total_minor DESC,order_id",['int64','int64'],'Tied102/106 rank3 next107 rank5;109/110 rank6 next108rank8.')
add('window.per_buyer','windows','Return payer name, order ID, then newest-first row number within each known payer, ordered by payer ID then row number.',"SELECT c.name,o.order_id,ROW_NUMBER() OVER (PARTITION BY c.customer_id ORDER BY o.order_date DESC,o.order_id DESC) AS position FROM customers c JOIN orders o ON c.customer_id=o.billing_customer_id WHERE o.status='completed' ORDER BY c.customer_id,position",['utf8','int64','int64'],'Ada107,102,101;Chen110104. Billing partition not shipping.',True)
add('window.running','windows','Return completed order ID then running sales cents by date and ID, using a rows frame, in that order.',"SELECT order_id,SUM(total_minor) OVER (ORDER BY order_date,order_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_minor FROM orders WHERE status='completed' ORDER BY order_date,order_id",['int64','int64'],'106/107 and109/110 same dates must accumulate rowwise separately.')
add('window.region_running','windows','For completed orders with matching billed customer records, return current billed region, order ID, then running sales cents within region by date and ID, ordered by region then date and ID.',"SELECT c.region,o.order_id,SUM(o.total_minor) OVER (PARTITION BY c.region ORDER BY o.order_date,o.order_id ROWS BETWEEN UNBOUNUNDED PRECEDING AND CURRENT ROW) AS running_minor FROM orders o JOIN customers c ON o.billing_customer_id=c.customer_id WHERE o.status='completed' ORDER BY c.region,o.order_date,o.order_id".replace('UNBOUNUNDED','UNBOUNDED'),['utf8','int64','int64'],'CH combinesAdaChen;104 then107 totals9000;1109500.',True)
add('window.lag','windows','Return completed order ID then previous completed order cents by date and ID, in that order.',"SELECT order_id,LAG(total_minor) OVER (ORDER BY order_date,order_id) AS previous_minor FROM orders WHERE status='completed' ORDER BY order_date,order_id",['int64','int64'],'First101 previousnull;108 previous1500;109 previous-100.')
add('window.top_per_buyer','windows','Return known billed buyer name then the ID of their completed order with the highest total cents, choosing the lower order ID on equal totals; sort by buyer ID.',"WITH ranked AS (SELECT c.customer_id,c.name,o.order_id,ROW_NUMBER() OVER (PARTITION BY c.customer_id ORDER BY o.total_minor DESC,o.order_id ASC) AS rn FROM customers c JOIN orders o ON c.customer_id=o.billing_customer_id WHERE o.status='completed') SELECT name,order_id FROM ranked WHERE rn=1 ORDER BY customer_id",['utf8','int64'],'Ada101,Chen104,Dario106,Éva108.',True)
add('window.final_limit','windows','Return the top three completed order IDs then dense sales rank, sorted by cents descending then ID.',"SELECT order_id,DENSE_RANK() OVER (ORDER BY total_minor DESC) AS sales_rank FROM orders WHERE status='completed' ORDER BY total_minor DESC,order_id LIMIT 3",['int64','int64'],'104rank1,101rank2,102rank3; rank computed before limit.')
# Sets/calculations (8)
add('sets.union_all','sets','Return billed buyer IDs from completed orders plus subscriber customer IDs from active subscriptions on April1,2024, retaining duplicates; output order does not matter.',"SELECT billing_customer_id AS customer_id FROM orders WHERE status='completed' UNION ALL SELECT customer_id FROM subscriptions WHERE status='active' AND start_date<='2024-04-01' AND (end_date IS NULL OR '2024-04-01'<end_date)",['int32'],'Ada4 copies,Chen3,Éva2,Dario1,99one; unionall bag.',ordered=False)
add('sets.union','sets','Return distinct billed buyer IDs occurring in completed orders or subscriber customer IDs from active subscriptions on April1,2024, sorted by ID.',"SELECT billing_customer_id AS customer_id FROM orders WHERE status='completed' UNION SELECT customer_id FROM subscriptions WHERE status='active' AND start_date<='2024-04-01' AND (end_date IS NULL OR '2024-04-01'<end_date) ORDER BY customer_id",['int32'],'1,3,4,5,99 duplicates eliminated.')
add('sets.intersect','sets','Return distinct known customer IDs that are both completed buyers and subscribers of any status, ascending.',"SELECT c.customer_id FROM customers c JOIN orders o ON c.customer_id=o.billing_customer_id WHERE o.status='completed' INTERSECT SELECT customer_id FROM subscriptions ORDER BY customer_id",['int32'],'1,3,5;4 buyer without subscription;2 subscriber without completed.',True)
add('sets.except','sets','Return known completed buyer IDs who have no subscription of any status, ascending.',"SELECT c.customer_id FROM customers c JOIN orders o ON c.customer_id=o.billing_customer_id WHERE o.status='completed' EXCEPT SELECT customer_id FROM subscriptions ORDER BY customer_id",['int32'],'4 only;99 not known.',True)
add('calculation.line_allocation','sets','For order101 return line number then allocated NET order cents after all its refunds, proportional to original signed line cents, using exact integer allocation, by line number.',"SELECT i.line_no,CAST((o.total_minor-COALESCE((SELECT SUM(r.refund_minor) FROM refunds r WHERE r.order_id=o.order_id),0))*i.line_minor/NULLIF((SELECT SUM(j.line_minor) FROM order_items j WHERE j.order_id=o.order_id),0) AS BIGINT) AS allocated_minor FROM order_items i JOIN orders o ON i.order_id=o.order_id WHERE i.order_id=101 ORDER BY i.line_no",['int16','int64'],'101 gross2500 minusrefunds500=net2000, weights1000/2500 and1500/2500; allocations800/1200 distinguish naïve rawline projection.')
add('calculation.zero_ratio','sets','For pending order105 return its signed weighted unit price as decimal cents, null for zero quantity.',"SELECT CAST(CAST(SUM(line_minor) AS DECIMAL(18,6))/NULLIF(CAST(SUM(quantity) AS DECIMAL(18,6)),0) AS DECIMAL(18,6)) AS weighted_price FROM order_items WHERE order_id=105",['decimal128(18,6)'],'0/0 policy null, not zero or arithmetic failure.')
add('calculation.tax','sets','Return completed order ID then exact tax amount in CHF, by order ID.',"SELECT order_id,tax_amount FROM orders WHERE status='completed' ORDER BY order_id",['int64','decimal128(18,2)'],'Exact decimal1.25,1.00,1.50,1.00,0.75,-0.05,0.25,0.25.')
add('calculation.exchange','sets','For each leap-day exchange rate, return currency, exact CHF value of100 foreign units, then value of negative100 units; round half away from zero to two decimals and order by currency.',"SELECT currency,CAST(ROUND(chf_per_unit*CAST(100 AS DECIMAL(18,0)),2) AS DECIMAL(18,2)) AS chf_value,CAST(ROUND(chf_per_unit*CAST(-100 AS DECIMAL(18,0)),2) AS DECIMAL(18,2)) AS negative_chf_value FROM exchange_rates WHERE rate_date=DATE '2024-02-29' ORDER BY currency",['utf8','decimal128(18,2)','decimal128(18,2)'],'CHF100.00/-100.00 EUR95.01/-95.01 USD90.00/-90.00; both signs ofEUR95.005 round away from zero.',oracle_sql="SELECT currency,chf_per_unit AS chf_value,chf_per_unit AS negative_chf_value FROM exchange_rates WHERE rate_date='2024-02-29' ORDER BY currency",oracle_rows=[(r[0],*[format((Decimal(r[2])*Decimal(amount)).quantize(Decimal('0.01'),rounding=ROUND_HALF_UP),'f') for amount in (100,-100)]) for r in sorted(tables['exchange_rates'][2])])

# Companion outcomes are desired semantic behavior; never waivers on result cases.
def companion(id,outcome,q,why,sql=None,context=None):
 q=re.sub(r'(?<=[A-Za-z])(?=\d)|(?<=\d)(?=[A-Za-z])',' ',q);why=re.sub(r'(?<=[A-Za-z])(?=\d)|(?<=\d)(?=[A-Za-z])',' ',why)
 write('expected/'+id+'.json',dict({'outcome':outcome},**({'diagnostic_contains':{'error.invalid_cast':'cast','error.division_zero':'zero','error.overflow':'overflow'}[id]} if outcome=='execution_error' else {})))
 c={'id':id,'primary_group':'companions','tags':['companion',outcome],'question':q,'expected':'expected/'+id+'.json','comparison':{'ordered':False,'assert_names':False,'assert_physical_types':False},'requirements':[why],'oracle_reasoning':why,'distinguishing_rows':[why]}
 if sql:c['sql']=sql
 if context:c['context']=context
 cases.append(c)
